sylphen_dd_fieldmapping.calculation:
// Enter id of dataport to be executed
$dataportId = {{ DEPENDENT DATAPORT ID }};

// provide parameters to use in dynamic import resource or in callback functions of dependent dataport
// leave empty to run dependent dataport with default import source
$parameters = {{ DEPENDENT DATAPORT PARAMETERS }};

if(($parameters || $params['lastCall']) && $dataportId) {
    $command = 'data-director:complete '.$dataportId.' --rm'.($parameters?' -f --parameters="'.str_replace(['"', '$', '`'], ['\"', '\$', '\`'], json_encode($parameters)).'"':'');

    if({{ DEPENDENT DATAPORT WAIT UNTIL FINISHED }}) {
        $params['logger']->info('Executing command "'.$command.'"');
        $output = \Blackbit\DataDirectorBundle\lib\Pim\Cli::exec($command);

        if(preg_match('/X-Data-Director-Run:\s*(.+)\n/', $output, $dependentRunId)) {
            $responseDocument = \Blackbit\DataDirectorBundle\Tools\Installer::getResultDocumentPath().'/result_'.{{ DEPENDENT DATAPORT ID }}.'_'.trim($dependentRunId[1]);

            if(file_exists($responseDocument)) {
                return \unserialize(\file_get_contents($responseDocument));
            }
        }
    } else {
        $params['logger']->info('Queuing command "'.$command.'"');
        $queue = new \Blackbit\DataDirectorBundle\model\Queue();
        $queue->create(['command' => $command, 'triggered_by' => 'Result callback function of dataport '.$params['context']['dataportId']]);
    }
}
